        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, 1e19);

        // actor deposits and successfully withdraws everything (releases lock in P)
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.withdrawAll();

        // a different, unrelated address (zero credit) calls withdrawAll:
        // in P the lock is free, so it succeeds; in M it is stuck, so it reverts
        address other = address(0xBEEF);
        vm.assume(other != actor);
        bool ok;
        vm.prank(other);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok, "withdrawAll by another actor after a completed withdraw must succeed");
    }
}

