pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        Reverter actor = new Reverter();
        vm.deal(address(actor), amount);
        actor.deposit{value: amount}(c);
        assertEq(c.credit(address(actor)), amount, "deposit must credit caller");
        bool ok = actor.withdrawAll(c);
        // General rule: a withdrawal whose payout fails must revert, keeping the caller's credit intact.
        assertTrue(ok && c.credit(address(actor)) == amount, "failed payout must revert and preserve credit");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
    function deposit(C c) external payable {
        c.deposit{value: msg.value}();
    }
    function withdrawAll(C c) external returns (bool) {
        try c.withdrawAll() { return true; } catch { return false; }
    }
    receive() external payable { revert(); }
}

