import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 1000 ether);

        // adversarial caller whose payout always fails (no receive/fallback)
        Reverter actor = new Reverter();

        vm.deal(address(actor), amount);
        vm.prank(address(actor));
        c.deposit{value: amount}();

        bool ok;
        vm.prank(address(actor));
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: a withdrawal that fails to pay out must not complete,
        // so the contract's ether must remain unchanged (or the call must revert).
        assertTrue(!ok || address(c).balance == amount, "failed payout must leave contract funds intact");
    }
}

contract Reverter {
    // no receive/fallback: low-level value calls to this contract fail
    function doNothing() external payable {}
}

