pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Rejecter attacker;

    function setUp() public { c = new C(); attacker = new Rejecter(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        vm.deal(address(attacker), amount);
        attacker.deposit{value: amount}(c);
        assertEq(c.credit(address(attacker)), amount);
        assertEq(address(c).balance, amount);

        attacker.withdraw(c);

        // In P the payout to the reverting callee fails and withdrawAll reverts,
        // so credit and contract ether are intact. In M the failure is swallowed:
        // credit is zeroed and ether leaves despite the failed payout.
        assertTrue(c.credit(address(attacker)) == amount && address(c).balance == amount);
    }
}

contract Rejecter {
    receive() external payable { revert(); }
    function deposit(C c) external payable { c.deposit{value: msg.value}(); }
    function withdraw(C c) external { c.withdrawAll(); }
}

