pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        Reentrant attacker = new Reentrant(c);
        vm.deal(address(attacker), amount);
        attacker.depositSelf();
        bool ok;
        try attacker.drain() { ok = true; } catch { ok = false; }
        assertTrue(ok, "withdrawAll must succeed even with a re-entrant recipient");
    }
}

contract Reentrant {
    C c;
    constructor(C _c) { c = _c; }
    function depositSelf() external {
        c.deposit{value: address(this).balance}();
    }
    function drain() external {
        c.withdrawAll();
    }
    receive() external payable {
        // re-enter; if the re-entrant call reverts, propagate so the outer call fails
        c.withdrawAll();
    }
}

