pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker();
        attacker.setTarget(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 4);
        vm.deal(address(this), amount);
        // deposit via the attacker so msg.sender credit belongs to the attacker
        vm.deal(address(attacker), amount);
        attacker.deposit(amount);
        attacker.attack();
        // Reference C: the re-entrant withdrawAll underflows balance and reverts,
        // so the outer call reverts and the contract still holds the funds.
        // Mutant M: credit is zeroed before the call, the re-entrant call is a
        // no-op, the outer call succeeds and drains the contract to 0.
        assertTrue(address(c).balance > 0);
    }
}

contract ReentrantAttacker {
    C target;
    bool attacking;

    function setTarget(C t) external { target = t; }

    function deposit(uint256 amount) external payable {
        require(msg.value == amount);
        target.deposit{value: amount}();
    }

    function attack() external {
        attacking = true;
        target.withdrawAll();
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            attacking = false;
            target.withdrawAll();
        }
    }
}
